insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.key='super_admin' on conflict do nothing;
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r join public.permissions p on p.key=any(case r.key when 'student' then array['posts.create','posts.edit','marketplace.create','marketplace.purchase','jobs.apply'] when 'faculty' then array['posts.create','posts.edit','projects.manage','events.manage','jobs.post'] when 'alumni' then array['posts.create','marketplace.create','marketplace.purchase','jobs.post','jobs.apply'] when 'vendor' then array['marketplace.create','food.manage'] when 'hostel_staff' then array['hostel.manage','hostel.allocate','hostel.outpasses.manage','hostel.complaints.manage','hostel.attendance.manage'] when 'moderator' then array['posts.moderate','stories.moderate','marketplace.moderate','moderation.manage'] when 'campus_admin' then array['users.read','users.write','events.manage','jobs.manage','hostel.manage','food.manage','notifications.manage','analytics.read'] else array[]::text[] end) where r.key<>'super_admin' on conflict do nothing;
